import { create } from "zustand";
import { Word, QuizQuestion, QuizSession, QuizChoiceQuestion, QuizSpellingQuestion, ImportRecord, QuizMode } from "@/types/game";
import { useGameStore } from "./useGameStore";

interface WordStore {
  words: Word[];
  wrongWords: Word[];
  quizSessionsLeft: number;
  currentLevel: number;
  quizSession: QuizSession | null;
  importHistory: ImportRecord[];

  loadWords: () => void;
  addWord: (spelling: string, meaning: string) => void;
  updateWord: (id: string, spelling: string, meaning: string) => void;
  deleteWord: (id: string) => void;
  importWords: (jsonStr: string) => { success: boolean; count: number; message: string };
  exportWords: () => { word: string; desc: string }[];
  loadImportHistory: () => void;
  clearImportHistory: () => void;

  addWrongWord: (word: Word) => void;
  handleCorrectAnswer: (wordId: string) => void;
  masterWord: (wordId: string) => void;
  removeWrongWord: (id: string) => void;
  clearWrongWords: () => void;

  resetLevelSessions: (level: number) => void;
  canStartQuiz: (mode?: QuizMode) => boolean;
  startQuiz: (mode?: QuizMode) => void;
  answerCurrentQuestion: (answer: string) => { correct: boolean };
  nextQuestion: () => { finished: boolean; won: boolean };
  setUserAnswer: (answer: string) => void;
  toggleLetterSelection: (letterIndex: number) => void;
  clearSelectedLetters: () => void;
  closeQuiz: () => void;
}

const STORAGE_KEY_WORDS = "block_game_words";
const STORAGE_KEY_WRONG_WORDS = "block_game_wrong_words";
const STORAGE_KEY_SESSIONS = "block_game_quiz_sessions";
const STORAGE_KEY_SESSIONS_LEVEL = "block_game_quiz_sessions_level";
const STORAGE_KEY_IMPORT_HISTORY = "block_game_import_history";

let saveWordTimer: number | null = null;
function flushSaveWord(state: {
  words: Word[];
  wrongWords: Word[];
  quizSessionsLeft: number;
  currentLevel: number;
  importHistory: ImportRecord[];
}) {
  saveWordTimer = null;
  try {
    localStorage.setItem(STORAGE_KEY_WORDS, JSON.stringify(state.words));
    localStorage.setItem(STORAGE_KEY_WRONG_WORDS, JSON.stringify(state.wrongWords));
    localStorage.setItem(STORAGE_KEY_SESSIONS, String(state.quizSessionsLeft));
    localStorage.setItem(STORAGE_KEY_SESSIONS_LEVEL, String(state.currentLevel));
    localStorage.setItem(STORAGE_KEY_IMPORT_HISTORY, JSON.stringify(state.importHistory));
  } catch (e) {
    console.error("保存单词数据失败", e);
  }
}
function saveWordData(
  state: {
    words: Word[];
    wrongWords: Word[];
    quizSessionsLeft: number;
    currentLevel: number;
    importHistory: ImportRecord[];
  },
  immediate = false
) {
  if (saveWordTimer !== null) {
    clearTimeout(saveWordTimer);
  }
  if (immediate) {
    saveWordTimer = null;
    flushSaveWord(state);
  } else {
    saveWordTimer = window.setTimeout(() => flushSaveWord(state), 300);
  }
}

const TOTAL_QUESTIONS = 10;
const MAX_WRONG = 3;
const CHOICE_RATIO = 0.7;
const SESSIONS_PER_LEVEL = 2;
const WRONG_INCREMENT = 2;
const CORRECT_DECREMENT = 1;

const shuffleArray = <T>(arr: T[]): T[] => {
  const result = [...arr];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
};

const generateShuffledLetters = (spelling: string): string[] => {
  const letters = spelling.split("");
  const letterCount = letters.length;
  const distractorCount = Math.min(4, Math.max(2, Math.floor(letterCount * 0.4)));
  const allLetters = "abcdefghijklmnopqrstuvwxyz";
  const existing = new Set(letters.map((l) => l.toLowerCase()));
  const distractors: string[] = [];

  while (distractors.length < distractorCount) {
    const random = allLetters[Math.floor(Math.random() * allLetters.length)];
    if (!existing.has(random)) {
      distractors.push(random);
      existing.add(random);
    }
  }

  return shuffleArray([...letters, ...distractors]);
};

const weightedPickWords = (words: Word[], count: number): Word[] => {
  if (words.length === 0) return [];
  const result: Word[] = [];
  const usedIds = new Set<string>();
  const pool = [...words];

  for (let i = 0; i < count && pool.length > 0; i++) {
    const totalWeight = pool.reduce((sum, w) => sum + 1 + w.wrongCount, 0);
    let random = Math.random() * totalWeight;

    let pickedIndex = 0;
    for (let j = 0; j < pool.length; j++) {
      random -= 1 + pool[j].wrongCount;
      if (random <= 0) {
        pickedIndex = j;
        break;
      }
    }

    const picked = pool[pickedIndex];
    if (!usedIds.has(picked.id)) {
      result.push(picked);
      usedIds.add(picked.id);
    }
    pool.splice(pickedIndex, 1);
  }

  while (result.length < count) {
    const available = words.filter((w) => !usedIds.has(w.id));
    if (available.length === 0) break;
    const w = available[Math.floor(Math.random() * available.length)];
    result.push(w);
    usedIds.add(w.id);
  }

  return result;
};

const generateQuestions = (words: Word[]): QuizQuestion[] => {
  const questions: QuizQuestion[] = [];
  const choiceCount = Math.round(TOTAL_QUESTIONS * CHOICE_RATIO);
  const spellingCount = TOTAL_QUESTIONS - choiceCount;

  const types: ("choice" | "spelling")[] = [
    ...Array(choiceCount).fill("choice"),
    ...Array(spellingCount).fill("spelling"),
  ];
  const shuffledTypes = shuffleArray(types);
  const pickedWords = weightedPickWords(words, TOTAL_QUESTIONS);

  for (let i = 0; i < TOTAL_QUESTIONS; i++) {
    const word = pickedWords[i % pickedWords.length];
    const type = shuffledTypes[i];

    if (type === "choice") {
      const otherWords = words.filter((w) => w.id !== word.id);
      const wrongOptions = shuffleArray(otherWords)
        .slice(0, 3)
        .map((w) => w.meaning);

      while (wrongOptions.length < 3) {
        wrongOptions.push(`干扰项${wrongOptions.length + 1}`);
      }

      const allOptions = shuffleArray([word.meaning, ...wrongOptions]);
      const correctIndex = allOptions.indexOf(word.meaning);

      questions.push({
        type: "choice",
        word,
        options: allOptions,
        correctIndex,
      } as QuizChoiceQuestion);
    } else {
      questions.push({
        type: "spelling",
        word,
        shuffledLetters: generateShuffledLetters(word.spelling),
      } as QuizSpellingQuestion);
    }
  }

  return questions;
};

const normalizeWord = (w: Partial<Word> & { spelling: string; meaning: string; wrongCount?: number }): Word => ({
  id: w.id || `word_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
  spelling: w.spelling.trim(),
  meaning: w.meaning.trim(),
  wrongCount: w.wrongCount || 0,
});

export const useWordStore = create<WordStore>((set, get) => ({
  words: [],
  wrongWords: [],
  quizSessionsLeft: SESSIONS_PER_LEVEL,
  currentLevel: 1,
  quizSession: null,
  importHistory: [],

  loadWords: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_WORDS);
      const parsed = raw ? JSON.parse(raw) : [];
      const words = parsed.map((w: unknown) => {
        const rec = w as Partial<Word> & { spelling?: string; meaning?: string; wrongCount?: number };
        return normalizeWord({
          spelling: rec.spelling || "",
          meaning: rec.meaning || "",
          wrongCount: (rec.wrongCount as number) || 0,
          ...rec,
        });
      });
      set({ words });
    } catch (e) {
      console.error("加载单词失败", e);
    }

    try {
      const raw = localStorage.getItem(STORAGE_KEY_WRONG_WORDS);
      const parsed = raw ? JSON.parse(raw) : [];
      const wrongWords = parsed.map((w: unknown) => {
        const rec = w as Partial<Word> & { spelling?: string; meaning?: string; wrongCount?: number };
        return normalizeWord({
          spelling: rec.spelling || "",
          meaning: rec.meaning || "",
          wrongCount: (rec.wrongCount as number) || WRONG_INCREMENT,
          ...rec,
        });
      });
      set({ wrongWords });
    } catch (e) {
      console.error("加载错题本失败", e);
    }

    try {
      const savedLevel = parseInt(localStorage.getItem(STORAGE_KEY_SESSIONS_LEVEL) || "1");
      const raw = localStorage.getItem(STORAGE_KEY_SESSIONS);
      set({
        currentLevel: savedLevel,
        quizSessionsLeft: raw ? parseInt(raw) : SESSIONS_PER_LEVEL,
      });
    } catch (e) {
      console.error("加载答题次数失败", e);
    }
  },

  addWord: (spelling, meaning) => {
    const word = normalizeWord({ spelling, meaning, wrongCount: 0 });
    const words = [...get().words, word];
    set({ words });
    saveWordData(get());
  },

  importWords: (jsonStr) => {
    try {
      const parsed = JSON.parse(jsonStr);
      if (!Array.isArray(parsed)) {
        return { success: false, count: 0, message: "格式错误：需要是数组格式" };
      }

      const validItems: Word[] = [];
      const rawItems: { word: string; desc: string }[] = [];
      for (const item of parsed) {
        const spelling = item.word || item.spelling;
        const meaning = item.desc || item.meaning;
        if (spelling && meaning) {
          validItems.push(normalizeWord({ spelling: String(spelling), meaning: String(meaning), wrongCount: 0 }));
          rawItems.push({ word: String(spelling), desc: String(meaning) });
        }
      }

      if (validItems.length === 0) {
        return { success: false, count: 0, message: "没有找到有效的单词数据" };
      }

      const existingSpellings = new Set(get().words.map((w) => w.spelling.toLowerCase()));
      const newWords = validItems.filter((w) => !existingSpellings.has(w.spelling.toLowerCase()));
      const duplicateCount = validItems.length - newWords.length;

      if (newWords.length === 0) {
        return { success: false, count: 0, message: `所有单词已存在（${duplicateCount} 个重复）` };
      }

      const words = [...get().words, ...newWords];
      set({ words });

      const record: ImportRecord = {
        id: `import_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        timestamp: Date.now(),
        count: newWords.length,
        words: rawItems,
      };
      const history = [...get().importHistory, record];
      set({ importHistory: history });
      saveWordData(get(), true);

      return {
        success: true,
        count: newWords.length,
        message: duplicateCount > 0 ? `成功导入 ${newWords.length} 个（跳过 ${duplicateCount} 个重复）` : `成功导入 ${newWords.length} 个单词`,
      };
    } catch {
      return { success: false, count: 0, message: "JSON 解析失败，请检查格式" };
    }
  },

  exportWords: () => {
    const { words } = get();
    return words.map((w) => ({ word: w.spelling, desc: w.meaning }));
  },

  loadImportHistory: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY_IMPORT_HISTORY);
      if (raw) {
        set({ importHistory: JSON.parse(raw) });
      }
    } catch (e) {
      console.error("加载导入历史失败", e);
    }
  },

  clearImportHistory: () => {
    set({ importHistory: [] });
    saveWordData(get());
  },

  updateWord: (id, spelling, meaning) => {
    const words = get().words.map((w) =>
      w.id === id ? { ...w, spelling: spelling.trim(), meaning: meaning.trim() } : w
    );
    set({ words });
    saveWordData(get());
  },

  deleteWord: (id) => {
    const words = get().words.filter((w) => w.id !== id);
    set({ words });

    const wrongWords = get().wrongWords.filter((w) => w.id !== id);
    set({ wrongWords });
    saveWordData(get());
  },

  addWrongWord: (word) => {
    const { words, wrongWords } = get();
    const updatedWords = words.map((w) =>
      w.id === word.id ? { ...w, wrongCount: w.wrongCount + WRONG_INCREMENT } : w
    );
    set({ words: updatedWords });

    const exists = wrongWords.some((w) => w.id === word.id);
    if (exists) {
      const updatedWrong = wrongWords.map((w) =>
        w.id === word.id ? { ...w, wrongCount: w.wrongCount + WRONG_INCREMENT } : w
      );
      set({ wrongWords: updatedWrong });
    } else {
      const newWrongWord = { ...word, wrongCount: (word.wrongCount || 0) + WRONG_INCREMENT };
      const updatedWrong = [...wrongWords, newWrongWord];
      set({ wrongWords: updatedWrong });
    }
    saveWordData(get());
  },

  handleCorrectAnswer: (wordId) => {
    const { words, wrongWords } = get();
    const targetWord = words.find((w) => w.id === wordId);
    if (!targetWord) return;

    const newWrongCount = Math.max(0, targetWord.wrongCount - CORRECT_DECREMENT);
    const updatedWords = words.map((w) => (w.id === wordId ? { ...w, wrongCount: newWrongCount } : w));
    set({ words: updatedWords });

    if (newWrongCount <= 0) {
      const updatedWrong = wrongWords.filter((w) => w.id !== wordId);
      set({ wrongWords: updatedWrong });
    } else {
      const updatedWrong = wrongWords.map((w) =>
        w.id === wordId ? { ...w, wrongCount: newWrongCount } : w
      );
      set({ wrongWords: updatedWrong });
    }
    saveWordData(get());
  },

  masterWord: (wordId) => {
    const words = get().words.filter((w) => w.id !== wordId);
    set({ words });

    const wrongWords = get().wrongWords.filter((w) => w.id !== wordId);
    set({ wrongWords });
    saveWordData(get());
  },

  removeWrongWord: (id) => {
    const wrongWords = get().wrongWords.filter((w) => w.id !== id);
    set({ wrongWords });
    saveWordData(get());
  },

  clearWrongWords: () => {
    set({ wrongWords: [] });
    saveWordData(get());
  },

  resetLevelSessions: (level: number) => {
    set({
      currentLevel: level,
      quizSessionsLeft: SESSIONS_PER_LEVEL,
    });
    saveWordData(get(), true);
  },

  canStartQuiz: (mode: QuizMode = "game") => {
    const { words, quizSessionsLeft } = get();
    if (words.length < 10) return false;
    if (mode === "farm" || mode === "refresh") return true;
    return quizSessionsLeft > 0;
  },

  startQuiz: (mode: QuizMode = "game") => {
    const { words, canStartQuiz } = get();
    if (!canStartQuiz(mode)) return;

    const questions = generateQuestions(words);

    set({
      quizSession: {
        questions,
        currentIndex: 0,
        correctCount: 0,
        wrongCount: 0,
        isFinished: false,
        isWon: false,
        userAnswer: "",
        selectedLetterIndices: [],
        mode,
      },
    });
  },

  answerCurrentQuestion: (answer) => {
    const { quizSession, addWrongWord, handleCorrectAnswer } = get();
    if (!quizSession || quizSession.isFinished) {
      return { correct: false };
    }

    const question = quizSession.questions[quizSession.currentIndex];
    let correct = false;
    let finalAnswer = answer;

    if (question.type === "choice") {
      correct = parseInt(answer) === question.correctIndex;
    } else {
      if (question.type === "spelling" && quizSession.selectedLetterIndices.length > 0) {
        finalAnswer = quizSession.selectedLetterIndices
          .map((i) => question.shuffledLetters[i])
          .join("");
      }
      correct = finalAnswer.trim().toLowerCase() === question.word.spelling.trim().toLowerCase();
    }

    if (correct) {
      handleCorrectAnswer(question.word.id);
    } else {
      addWrongWord(question.word);
    }

    const newCorrect = quizSession.correctCount + (correct ? 1 : 0);
    const newWrong = quizSession.wrongCount + (correct ? 0 : 1);

    // 答错超过上限则立即结束答题
    const shouldFinish = newWrong > MAX_WRONG;

    set({
      quizSession: {
        ...quizSession,
        correctCount: newCorrect,
        wrongCount: newWrong,
        isFinished: shouldFinish ? true : quizSession.isFinished,
        isWon: shouldFinish ? false : quizSession.isWon,
        userAnswer: "",
      },
    });

    return { correct };
  },

  nextQuestion: () => {
    const { quizSession, quizSessionsLeft } = get();
    if (!quizSession || quizSession.isFinished) {
      return { finished: true, won: false };
    }

    const nextIndex = quizSession.currentIndex + 1;
    const allDone = nextIndex >= TOTAL_QUESTIONS;
    const won = allDone && quizSession.wrongCount <= MAX_WRONG;
    const finished = allDone;

    if (finished && won) {
      if (quizSession.mode === "game") {
        const newSessionsLeft = quizSessionsLeft - 1;
        set({ quizSessionsLeft: newSessionsLeft });
        saveWordData(get());
        useGameStore.getState().checkAndClearFailAfterQuiz();
      }
    }

    set({
      quizSession: {
        ...quizSession,
        currentIndex: finished ? quizSession.currentIndex : nextIndex,
        isFinished: finished,
        isWon: won,
        userAnswer: "",
        selectedLetterIndices: [],
      },
    });

    return { finished, won };
  },

  setUserAnswer: (answer) => {
    const { quizSession } = get();
    if (!quizSession) return;
    set({ quizSession: { ...quizSession, userAnswer: answer } });
  },

  toggleLetterSelection: (letterIndex) => {
    const { quizSession } = get();
    if (!quizSession) return;
    const question = quizSession.questions[quizSession.currentIndex];
    if (question.type !== "spelling") return;

    const selected = quizSession.selectedLetterIndices;
    const existingPos = selected.indexOf(letterIndex);

    if (existingPos !== -1) {
      const newSelected = selected.slice(0, existingPos);
      set({ quizSession: { ...quizSession, selectedLetterIndices: newSelected } });
    } else {
      if (selected.length >= question.word.spelling.length) return;
      const newSelected = [...selected, letterIndex];
      set({ quizSession: { ...quizSession, selectedLetterIndices: newSelected } });
    }
  },

  clearSelectedLetters: () => {
    const { quizSession } = get();
    if (!quizSession) return;
    set({ quizSession: { ...quizSession, selectedLetterIndices: [] } });
  },

  closeQuiz: () => {
    set({ quizSession: null });
  },
}));

// Store 创建后立即从 localStorage 加载数据，确保任何页面刷新后数据都可用
useWordStore.getState().loadWords();
