import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import { Trophy, Settings, BookOpen, AlertCircle, X, Sprout } from "lucide-react";
import SettingsModal from "@/components/SettingsModal";
import ConfirmModal from "@/components/ConfirmModal";
import WordListModal from "@/components/WordListModal";
import MigrateModal from "@/components/MigrateModal";
import RankingModal from "@/components/RankingModal";
import OnlinePlayersBadge from "@/components/OnlinePlayersBadge";
import { useWordStore } from "@/store/useWordStore";
import { useFarmStore } from "@/store/useFarmStore";
import { getUserInfo } from "@/utils/userInfo";

export default function StartScreen() {
  const navigate = useNavigate();
  const [hasSave] = useState(() => localStorage.getItem("block_game_save") !== null);
  const [showSettings, setShowSettings] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [showWordList, setShowWordList] = useState(false);
  const [showMigrate, setShowMigrate] = useState(false);
  const [showRanking, setShowRanking] = useState(false);
  const [importData, setImportData] = useState<{
    userInfo: { uuid: string; nickname: string };
    gameData?: { level?: number; score?: number; coins?: number };
    wordData?: { words?: unknown[]; wrongWords?: unknown[]; currentLevel?: number; quizSessionsLeft?: number };
    bestScore?: number;
  } | null>(null);
  const [showRulesUpdated, setShowRulesUpdated] = useState(() => {
    return localStorage.getItem("block_game_rules_updated") === "1";
  });
  const [bestLevel] = useState(() => parseInt(localStorage.getItem("block_game_best") || "0"));

  const loadWords = useWordStore((s) => s.loadWords);
  const words = useWordStore((s) => s.words);
  const resetLevelSessions = useWordStore((s) => s.resetLevelSessions);
  const loadFarm = useFarmStore((s) => s.loadFarm);
  const plantedCrops = useFarmStore((s) => s.plantedCrops);
  const isReadyToHarvest = useFarmStore((s) => s.isReadyToHarvest);

  useEffect(() => {
    loadWords();
    loadFarm();
  }, [loadWords, loadFarm]);

  const readyCount = plantedCrops.filter((c) => isReadyToHarvest(c)).length;
  const growingCount = plantedCrops.length - readyCount;
  const farmStatus = readyCount > 0
    ? `(${readyCount} 个可收获 🍎)`
    : growingCount > 0
    ? `(${growingCount} 个成长中 🌱)`
    : "(空空如也 🌾)";

  const dismissRulesUpdated = () => {
    setShowRulesUpdated(false);
    localStorage.removeItem("block_game_rules_updated");
  };

  const handleNewGame = () => {
    if (hasSave) {
      setShowConfirm(true);
    } else {
      resetLevelSessions(1);
      navigate("/game?fresh=1");
    }
  };

  const confirmNewGame = () => {
    localStorage.removeItem("block_game_save");
    resetLevelSessions(1);
    setShowConfirm(false);
    navigate("/game?fresh=1");
  };

  const handleContinueGame = async () => {
    // 在用户手势上下文中读取剪贴板，检测迁移数据
    try {
      if (navigator.clipboard && navigator.clipboard.readText) {
        const text = await navigator.clipboard.readText();
        const parsed = JSON.parse(text);
        
        // 验证数据格式
        if (parsed.userInfo && parsed.gameData && parsed.wordData) {
          // 比较 UUID，如果相同则忽略
          const currentUser = getUserInfo();
          if (parsed.userInfo.uuid !== currentUser.uuid) {
            setImportData(parsed);
            setShowMigrate(true);
            return; // 阻止导航，等待用户确认迁移
          }
        }
      }
    } catch {
      // 无法读取剪贴板或解析失败，忽略
    }
    
    // 没有迁移数据或 UUID 相同，直接进入游戏
    navigate("/game");
  };

  const handleMigrate = () => {
    if (!importData) return;
    
    try {
      const data = importData as Record<string, unknown>;
      const userInfo = data.userInfo as Record<string, unknown>;
      const gameData = data.gameData as Record<string, unknown> | undefined;
      const wordData = data.wordData as Record<string, unknown> | undefined;
      const bestScore = data.bestScore as number | undefined;
      
      // 1. 导入用户信息
      localStorage.setItem("block_game_user_info", JSON.stringify({
        uuid: userInfo.uuid,
        nickname: userInfo.nickname,
      }));
      
      // 2. 导入游戏数据
      if (gameData) {
        localStorage.setItem("block_game_save", JSON.stringify(gameData));
      }
      
      // 3. 导入单词数据
      if (wordData) {
        localStorage.setItem("block_game_words", JSON.stringify(wordData.words || []));
        localStorage.setItem("block_game_wrong_words", JSON.stringify(wordData.wrongWords || []));
        localStorage.setItem("block_game_quiz_sessions_level", String(wordData.currentLevel || 1));
        localStorage.setItem("block_game_quiz_sessions", String(wordData.quizSessionsLeft ?? 2));
      }
      
      // 4. 导入最高分
      if (bestScore !== undefined) {
        localStorage.setItem("block_game_best", String(bestScore));
      }
      
      setImportData(null);
      setShowMigrate(false);
      
      // 迁移完成后进入游戏
      navigate("/game");
    } catch (e) {
      console.error("导入失败", e);
    }
  };

  return (
    <div
      className="min-h-screen w-full flex flex-col items-center justify-center relative overflow-hidden touch-none overscroll-none"
      style={{
        backgroundImage:
          "url(https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=pixel%20art%20landscape%20green%20grass%20field%20with%20flowers%20distant%20forest%20trees%20blue%20sky%20warm%20sunlight%208bit%20style%20game%20background&image_size=portrait_9_16)",
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
      }}
    >
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "linear-gradient(180deg, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0.2) 40%, rgba(0,0,0,0.45) 100%)",
        }}
      />

      {showRulesUpdated && (
        <div className="absolute top-0 left-0 right-0 z-30 mx-4 mt-4">
          <div className="flex items-start gap-3 p-3 bg-amber-500/15 backdrop-blur-md border border-amber-400/30 rounded-xl shadow-lg">
            <AlertCircle size={18} className="text-amber-400 shrink-0 mt-0.5" />
            <p className="text-amber-200 text-sm flex-1">
              游戏规则已更新，历史最高记录已重置
            </p>
            <button
              onClick={dismissRulesUpdated}
              className="p-0.5 rounded hover:bg-amber-500/20 transition-all shrink-0"
            >
              <X size={16} className="text-amber-400" />
            </button>
          </div>
        </div>
      )}

      <OnlinePlayersBadge />

      <div className="absolute top-4 right-4 z-20">
        <button
          onClick={() => setShowSettings(true)}
          className="w-12 h-12 rounded-full bg-slate-800/60 backdrop-blur-sm border border-slate-600/50 flex items-center justify-center text-white hover:scale-110 active:scale-95 transition-transform"
        >
          <Settings size={22} />
        </button>
      </div>

      <div className="relative z-10 flex flex-col items-center gap-8 px-6">
        <div className="text-center">
          <h1 className="text-5xl font-bold text-amber-200 drop-shadow-lg tracking-wider mb-2">
            消了又消
          </h1>
          <p className="text-amber-100/70 text-lg">移动砖块，两两消除</p>
        </div>

        {bestLevel > 0 && (
          <button
            onClick={() => setShowRanking(true)}
            className="flex items-center gap-3 bg-amber-500/15 backdrop-blur-sm rounded-2xl px-6 py-3 border border-amber-400/30 hover:bg-amber-500/25 hover:scale-105 active:scale-95 transition-all"
          >
            <Trophy size={24} className="text-amber-400" />
            <div className="text-left">
              <p className="text-amber-300/70 text-xs">最高纪录</p>
              <p className="text-amber-200 font-bold text-lg">第 {bestLevel} 关</p>
            </div>
          </button>
        )}

        <div className="flex flex-col gap-4 w-full max-w-xs">
          <button
            onClick={() => navigate("/farm")}
            className="flex items-center justify-center gap-2 py-3 bg-emerald-500/20 backdrop-blur-sm border border-emerald-400/30 text-emerald-200 font-bold rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-transform"
          >
            <Sprout size={20} />
            <span>我的农场</span>
            {farmStatus && (
              <span className={`text-sm ${
                readyCount > 0
                  ? "text-rose-400"
                  : growingCount > 0
                  ? "text-amber-400"
                  : "text-slate-400"
              }`}>
                {farmStatus}
              </span>
            )}
          </button>

          <button
            onClick={() => setShowWordList(true)}
            className="flex items-center justify-center gap-2 py-3 bg-emerald-500/20 backdrop-blur-sm border border-emerald-400/30 text-emerald-200 font-bold rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-transform"
          >
            <BookOpen size={20} />
            <span>我的单词本</span>
            <span className="text-emerald-400/70 text-sm">({words.length})</span>
          </button>

          <button
            onClick={handleNewGame}
            className="w-full py-4 bg-gradient-to-r from-amber-500 via-orange-500 to-red-500 text-white font-bold text-xl rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-transform"
          >
            🎮 {hasSave ? "重新开始" : "新的开始"}
          </button>

          <button
            onClick={handleContinueGame}
            disabled={!hasSave}
            className={`w-full py-4 font-bold text-xl rounded-xl shadow-lg transition-all ${
              hasSave
                ? "bg-gradient-to-r from-emerald-500 via-teal-500 to-cyan-500 text-white hover:scale-105 active:scale-95"
                : "bg-slate-600/50 text-slate-400 cursor-not-allowed"
            }`}
          >
            {hasSave ? "📂 继续游戏" : "📂 暂无存档"}
          </button>
        </div>

        <p className="text-amber-100/40 text-sm mt-8">
          10×14 · 35种图标 · 移动消除
        </p>
      </div>

      <SettingsModal open={showSettings} onClose={() => setShowSettings(false)} />
      <WordListModal open={showWordList} onClose={() => setShowWordList(false)} />
      <RankingModal open={showRanking} onClose={() => setShowRanking(false)} />
      <ConfirmModal
        open={showConfirm}
        title="重新开始"
        message="确定要重新开始吗？当前进度将被清除"
        confirmText="确认重新开始"
        cancelText="取消"
        onConfirm={confirmNewGame}
        onCancel={() => setShowConfirm(false)}
      />
      <MigrateModal
        open={showMigrate}
        importData={importData}
        onClose={() => {
          setShowMigrate(false);
          setImportData(null);
        }}
        onConfirm={handleMigrate}
      />
    </div>
  );
}
