import { SEED_CONFIGS } from "@/types/game";
import { supabase } from "@/utils/supabase";

export interface FarmSnapshot {
  plantedCrops: Array<{
    id: string;
    seedType: string;
    plantedAt: number;
    plotIndex: number;
  }>;
  stolenRecords: Array<{
    plotIndex: number;
    seedType: string;
    stolenAt: number;
    thiefUuid: string;
    thiefNickname: string;
  }>;
  warehouse: Record<string, number>;
  totalPlots: number;
  openedPlots: number;
  unlockedSeeds: string[];
  snapshotAt: number;
}

export interface RankingPlayer {
  uuid: string;
  nickname: string;
  bestLevel: number;
  updatedAt: number;
  farmData?: FarmSnapshot;
}

interface PlayerRow {
  uuid: string;
  nickname: string;
  best_level: number;
  updated_at: number;
}

interface FarmRow {
  uuid: string;
  planted_crops: Array<{ id: string; seed_type: string; planted_at: number; plot_index: number }>;
  stolen_records: Array<{ plot_index: number; seed_type: string; stolen_at: number; thief_uuid: string; thief_nickname: string }>;
  warehouse: Record<string, number>;
  total_plots: number;
  opened_plots: number;
  unlocked_seeds: string[];
  snapshot_at: number;
}

function farmRowToSnapshot(row: FarmRow | null): FarmSnapshot | undefined {
  if (!row) return undefined;
  return {
    plantedCrops: (row.planted_crops || []).map((c) => ({
      id: c.id,
      seedType: c.seed_type,
      plantedAt: c.planted_at,
      plotIndex: c.plot_index,
    })),
    stolenRecords: (row.stolen_records || []).map((r) => ({
      plotIndex: r.plot_index,
      seedType: r.seed_type,
      stolenAt: r.stolen_at,
      thiefUuid: r.thief_uuid,
      thiefNickname: r.thief_nickname,
    })),
    warehouse: row.warehouse || {},
    totalPlots: row.total_plots || 0,
    openedPlots: row.opened_plots || 0,
    unlockedSeeds: row.unlocked_seeds || [],
    snapshotAt: row.snapshot_at || 0,
  };
}

function snapshotToFarmRow(snapshot: FarmSnapshot): Omit<FarmRow, "uuid"> {
  return {
    planted_crops: snapshot.plantedCrops.map((c) => ({
      id: c.id,
      seed_type: c.seedType,
      planted_at: c.plantedAt,
      plot_index: c.plotIndex,
    })),
    stolen_records: snapshot.stolenRecords.map((r) => ({
      plot_index: r.plotIndex,
      seed_type: r.seedType,
      stolen_at: r.stolenAt,
      thief_uuid: r.thiefUuid,
      thief_nickname: r.thiefNickname,
    })),
    warehouse: snapshot.warehouse,
    total_plots: snapshot.totalPlots,
    opened_plots: snapshot.openedPlots,
    unlocked_seeds: snapshot.unlockedSeeds,
    snapshot_at: snapshot.snapshotAt,
  };
}

function playerRowToRanking(row: PlayerRow, farmRow: FarmRow | null): RankingPlayer {
  return {
    uuid: row.uuid,
    nickname: row.nickname,
    bestLevel: row.best_level,
    updatedAt: row.updated_at,
    farmData: farmRowToSnapshot(farmRow),
  };
}

let rankingCache: RankingPlayer[] | null = null;
let rankingCacheAt = 0;
const RANKING_CACHE_MS = 30 * 1000;

interface PendingUpload {
  uuid: string;
  nickname: string;
  bestLevel: number;
  farmData?: FarmSnapshot;
}

let uploadBatchTimer: number | null = null;
let uploadBatch: PendingUpload[] = [];

function mergeUploads(batch: PendingUpload[]): PendingUpload[] {
  const map = new Map<string, PendingUpload>();
  for (const item of batch) {
    const existing = map.get(item.uuid);
    if (!existing) {
      map.set(item.uuid, { ...item });
    } else {
      map.set(item.uuid, {
        ...item,
        bestLevel: Math.max(existing.bestLevel, item.bestLevel),
        farmData: item.farmData || existing.farmData,
      });
    }
  }
  return Array.from(map.values());
}

async function flushUploadBatch() {
  uploadBatchTimer = null;
  const batch = uploadBatch;
  uploadBatch = [];
  if (batch.length === 0) return;

  const merged = mergeUploads(batch);
  for (const item of merged) {
    await doUploadScore(item.uuid, item.nickname, item.bestLevel, item.farmData);
  }
}

export async function fetchRanking(force = false): Promise<RankingPlayer[]> {
  const now = Date.now();
  if (!force && rankingCache && now - rankingCacheAt < RANKING_CACHE_MS) {
    return rankingCache;
  }

  try {
    const { data: players, error: playersError } = await supabase
      .from("players")
      .select("*")
      .order("best_level", { ascending: false })
      .order("updated_at", { ascending: false });

    if (playersError) {
      console.error("获取排行榜失败:", playersError.message);
      return rankingCache || [];
    }

    const { data: farms, error: farmsError } = await supabase
      .from("farms")
      .select("*");

    if (farmsError) {
      console.warn("获取农场数据失败:", farmsError.message);
    }

    const farmMap = new Map<string, FarmRow>();
    (farms || []).forEach((f) => farmMap.set(f.uuid, f as FarmRow));

    const result = (players || [])
      .filter((p) => p && p.uuid && typeof p.best_level === "number")
      .map((p) => playerRowToRanking(p as PlayerRow, farmMap.get(p.uuid) || null));

    rankingCache = result;
    rankingCacheAt = now;
    return result;
  } catch (e) {
    console.error("请求排行榜失败:", e);
    return rankingCache || [];
  }
}

export async function uploadScore(
  uuid: string,
  nickname: string,
  bestLevel: number,
  farmData?: FarmSnapshot
): Promise<boolean> {
  if (!uuid) {
    console.warn("uploadScore: uuid 为空，跳过");
    return false;
  }

  uploadBatch.push({ uuid, nickname, bestLevel, farmData });
  if (uploadBatchTimer !== null) {
    clearTimeout(uploadBatchTimer);
  }
  uploadBatchTimer = window.setTimeout(flushUploadBatch, 50);
  return true;
}

async function doUploadScore(
  uuid: string,
  nickname: string,
  bestLevel: number,
  farmData?: FarmSnapshot
): Promise<boolean> {
  try {
    const now = Date.now();

    const { data: rows, error: fetchError } = await supabase
      .from("players")
      .select("best_level")
      .eq("uuid", uuid)
      .limit(1);

    if (fetchError) {
      console.error("查询玩家数据失败:", fetchError.message);
      return false;
    }

    const existing = rows && rows.length > 0 ? rows[0] : null;

    if (existing && bestLevel <= existing.best_level && !farmData) {
      return true;
    }

    const finalBestLevel = existing ? Math.max(bestLevel, existing.best_level) : bestLevel;

    const { error: playerError } = await supabase
      .from("players")
      .upsert(
        { uuid, nickname, best_level: finalBestLevel, updated_at: now },
        { onConflict: "uuid" }
      );

    if (playerError) {
      console.error("上传排行榜失败:", playerError.message);
      return false;
    }

    if (farmData) {
      const farmRow = snapshotToFarmRow(farmData);
      const { error: farmError } = await supabase
        .from("farms")
        .upsert(
          { uuid, ...farmRow },
          { onConflict: "uuid" }
        );

      if (farmError) {
        console.error("上传农场数据失败:", farmError.message);
        return false;
      }
    }

    if (!existing || bestLevel > existing.best_level) {
      rankingCache = null;
    }

    return true;
  } catch (e) {
    console.error("上传排行榜异常:", e);
    return false;
  }
}

export async function uploadFarmData(uuid: string, nickname: string, farmData: FarmSnapshot): Promise<boolean> {
  const bestLevel = parseInt(localStorage.getItem("block_game_best") || "0");
  return uploadScore(uuid, nickname, bestLevel, farmData);
}

export async function fetchPlayerFarm(uuid: string): Promise<FarmSnapshot | null> {
  try {
    const { data, error } = await supabase
      .from("farms")
      .select("*")
      .eq("uuid", uuid)
      .limit(1);

    if (error) {
      console.error("获取玩家农场失败:", error.message);
      return null;
    }

    if (!data || data.length === 0) return null;

    return farmRowToSnapshot(data[0] as FarmRow) || null;
  } catch (e) {
    console.error("请求玩家农场异常:", e);
    return null;
  }
}

interface BatchStealItem {
  targetUuid: string;
  cropId: string;
  seedType: string;
  thiefUuid: string;
  thiefNickname: string;
}

export async function stealCropBatch(items: BatchStealItem[]): Promise<{ success: boolean; message: string }> {
  if (items.length === 0) return { success: true, message: "nothing to do" };

  try {
    const targetUuids = [...new Set(items.map((i) => i.targetUuid))];
    const now = Date.now();

    const { data: farms, error: farmsError } = await supabase
      .from("farms")
      .select("*")
      .in("uuid", targetUuids);

    if (farmsError) {
      console.error("批量偷菜：获取农场失败", farmsError.message);
      return { success: false, message: "数据同步失败，请稍后再试" };
    }

    const farmMap = new Map<string, FarmRow>();
    (farms || []).forEach((f) => farmMap.set(f.uuid, f as FarmRow));

    let successCount = 0;
    const updates: Array<{ uuid: string; farm: FarmRow }> = [];

    for (const item of items) {
      const target = farmMap.get(item.targetUuid);
      if (!target) continue;

      const crops = target.planted_crops || [];
      const cropIdx = crops.findIndex((c) => c.id === item.cropId);
      if (cropIdx < 0) continue;

      const crop = crops[cropIdx];
      const config = SEED_CONFIGS[crop.seed_type as keyof typeof SEED_CONFIGS];
      if (!config) continue;

      const totalMs = config.growthHours * 3600000;
      const elapsedMs = now - crop.planted_at;
      if (elapsedMs < totalMs) continue;
      const overripeMs = elapsedMs - totalMs;
      if (overripeMs < 3600000) continue;

      const newCrops = crops.filter((c) => c.id !== item.cropId);

      const newRecord = {
        plot_index: crop.plot_index,
        seed_type: crop.seed_type,
        stolen_at: now,
        thief_uuid: item.thiefUuid,
        thief_nickname: item.thiefNickname,
      };
      const oldRecords = target.stolen_records || [];
      const newRecords = [...oldRecords, newRecord].slice(-30);

      const updatedFarm: FarmRow = {
        ...target,
        planted_crops: newCrops,
        stolen_records: newRecords,
        snapshot_at: now,
      };

      farmMap.set(item.targetUuid, updatedFarm);
      updates.push({ uuid: item.targetUuid, farm: updatedFarm });
      successCount++;
    }

    if (successCount === 0) {
      return { success: false, message: "没有可偷的作物" };
    }

    const uniqueUpdates = new Map<string, FarmRow>();
    updates.forEach((u) => uniqueUpdates.set(u.uuid, u.farm));

    for (const [uuid, farm] of uniqueUpdates) {
      const { error } = await supabase
        .from("farms")
        .upsert({ uuid, ...farm }, { onConflict: "uuid" });
      if (error) {
        console.error(`写回农场数据失败 (${uuid}):`, error.message);
      }
    }

    return { success: true, message: `成功同步 ${successCount} 次偷菜` };
  } catch (e) {
    console.error("批量偷菜异常:", e);
    return { success: false, message: "偷菜失败，请稍后再试" };
  }
}
